begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
-- Privileged import fixture: reproduce legacy removed performance, impossible via ordinary app writes.
alter table workout_sets disable trigger user;
alter table workout_sets enable trigger user;
update workout_exercises set logging_kind='legacy' where id=md5('re_oldadded')::uuid;
update workout_sets set entered_weight=235,entered_unit='lb' where id=md5('rs_heavier5')::uuid;
update workout_sets set entered_weight=50,entered_unit='lb' where id=md5('rs_lb50')::uuid;
select ok(not has_function_privilege('anon','public.personal_records(uuid[],text,uuid,integer,uuid[],uuid[],integer[])','execute'),'anonymous records denied');
select ok(not has_function_privilege('service_role','public.record_metrics(uuid,uuid[])','execute'),'service record access not granted');
select ok((select bool_and(not prosecdef and proconfig @> array['search_path=""']) from pg_proc where proname in('record_performances','record_metrics','personal_records','workout_achievements','record_load_bests','history_achievement_counts')),'all record reads use invoker RLS and empty search path');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('records_a')::uuid,'role','authenticated')::text,true);
create function pg_temp.best(slug text,metric text,key numeric default 0) returns numeric language sql as $$ select max(m.value) from public.record_metrics((select id from public.exercises where exercises.slug=$1))m where m.metric=$2 and m.load_key=$3 $$;
select is(pg_temp.best('barbell_bench_press','actual_rm',3),100::numeric,'STRICT: 235 lb x 5 does not raise actual 3RM above 100 kg');
select is(pg_temp.best('barbell_bench_press','actual_rm',5),106.594::numeric,'actual 5RM requires exactly five repetitions');
select is(pg_temp.best('barbell_bench_press','actual_rm',1),90::numeric,'actual 1RM is completed single, separate from heavier 5RM');
select is(pg_temp.best('barbell_bench_press','actual_rm',8),80::numeric,'engine supports exact 8RM');
select is(pg_temp.best('barbell_bench_press','actual_rm',2),null::numeric,'missing exact rep category absent, never estimated');
select is((select value from record_metrics() where session_id=md5('r_baseline')::uuid and metric='volume'),750::numeric,'volume sums all eligible working sets and excludes same-session warm-ups');
select is(pg_temp.best('barbell_bench_press','heaviest'),106.594::numeric,'heaviest uses any positive completed rep count');
select is(pg_temp.best('barbell_bench_press','estimated_1rm'),124.360::numeric,'separate Epley estimate rounded once to canonical precision');
select is((select value from record_metrics() where session_id=md5('r_single')::uuid and metric='estimated_1rm'),90::numeric,'Epley successful single equals actual load');
select is(pg_temp.best('machine_leg_extension','estimated_1rm'),null::numeric,'11 reps outside estimate range');
select is((select value from record_metrics() where session_id=md5('r_heavier5')::uuid and metric='volume'),532.970::numeric,'per-exercise session volume actual weight times reps');
select is((select count(*)::int from record_performances() where session_id in(select md5('r_'||n)::uuid from unnest(array['warm','pending','abandoned','deleted','removed','unconfirmed','assist','duration','oldadded']) n)),0,'exclude warm-ups, suggestions, abandoned, deleted, removed, unconfirmed, unsupported, ambiguous legacy added load');
select is(pg_temp.best('incline_barbell_bench_press','actual_rm',3),1000::numeric,'variations remain independent');
select is(pg_temp.best('pull_up','bodyweight_reps'),12::numeric,'bodyweight reps do not use added load or assumed body mass');
select is(pg_temp.best('pull_up','added_load'),20::numeric,'positive added external resistance distinct');
select is((select value from record_metrics() where session_id=md5('r_added')::uuid and metric='volume'),120::numeric,'added volume uses external resistance only');
select is((select count(*)::int from record_metrics() where category='bodyweight' and metric in('heaviest','volume','estimated_1rm','actual_rm')),0,'no bodyweight force, volume or estimated RM fabrication');
select is((select jsonb_array_length(record_load_bests((select id from exercises where slug='standing_dumbbell_curl')))),1,'equivalent canonical 50 lb sets share a load bucket');
select is((record_load_bests((select id from exercises where slug='standing_dumbbell_curl'))->0->>'value')::numeric,10::numeric,'same canonical load chooses most reps');
select is(workout_achievements(md5('r_baseline')::uuid),'[]'::jsonb,'historical baselines never celebrated');
select is(workout_achievements(md5('r_single')::uuid),'[]'::jsonb,'first exact rep metric is a baseline, not improvement');
select is(workout_achievements(md5('r_tie')::uuid),'[]'::jsonb,'ties are not new records');
select ok(exists(select 1 from jsonb_array_elements(workout_achievements(md5('r_heavier5')::uuid))a where a->>'metric'='heaviest'),'genuine completed improvement earns achievement');
select ok(not exists(select 1 from jsonb_array_elements(workout_achievements(md5('r_heavier5')::uuid))a where a->>'metric'='actual_rm' and a->>'load_key'='3'),'heavier five never announces 3RM');
select is(workout_achievements(md5('r_heavier5')::uuid),workout_achievements(md5('r_heavier5')::uuid),'refresh recognition deterministic without duplicate rows');
select is(workout_achievements(md5('r_abandoned')::uuid),'[]'::jsonb,'abandonment never recognized');
select is((history_achievement_counts(array[md5('r_heavier5')::uuid])->>(md5('r_heavier5')::uuid)::text)::int,1,'history batch count agrees with diverse presentation');
select ok(not exists(select 1 from jsonb_array_elements(personal_records(array[(select id from exercises where slug='barbell_bench_press')]))e cross join jsonb_array_elements(e->'metrics')m where m->>'metric'='actual_rm' and (m->>'load_key')::int not in(1,3,5)),'summary limits actual RM display to MVP 1,3,5');
select ok(exists(select 1 from jsonb_array_elements(personal_records(p_ids=>array[(select id from exercises where slug='barbell_bench_press')],p_exact_reps=>array[8]))e cross join jsonb_array_elements(e->'metrics')m where m->>'metric'='actual_rm' and m->>'load_key'='8'),'optional exact-rep queries supported');
select throws_ok($$select personal_records(p_limit=>1000)$$,'22023',null,'unbounded record queries denied');
select throws_ok($$select record_load_bests((select id from exercises where slug='barbell_bench_press'),50,null)$$,'22023',null,'malformed load cursor rejected');
reset role;
update workout_sets set actual_weight_kg=95 where id=md5('rs_baseline')::uuid;
set local role authenticated;
select is(pg_temp.best('barbell_bench_press','actual_rm',3),95::numeric,'source correction recomputes exact record, not stale derived state');
select set_config('request.jwt.claims',json_build_object('sub',md5('records_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from record_performances()),0,'foreign raw eligible sets hidden');
select is((select count(*)::int from record_metrics()),0,'foreign computed metrics hidden');
select is(personal_records(),'[]'::jsonb,'foreign records hidden');
select is(record_load_bests((select id from exercises where slug='barbell_bench_press')),'[]'::jsonb,'foreign load records hidden');
select is(workout_achievements(md5('r_heavier5')::uuid),'[]'::jsonb,'foreign session achievements hidden');
select is(history_achievement_counts(array[md5('r_heavier5')::uuid]),'{}'::jsonb,'foreign history counts hidden');
select * from finish();rollback;
